//! Logical scalar/member JSON from the original diplomacy path/profile kernels.
use super::*;
use crate::incremental_runtime_revocation::BusinessDiffProcessingWorkV1;
use oasis7_proto::memory_budget::MemoryReservation;
use std::{io::{self,Write},mem::size_of};
fn bad()->ValueTreeError{closure::invalid()}
fn limited()->ValueTreeError{ValueTreeError::ResourceLimited("diplomacy projection cells")}
fn pay(p:&mut BusinessDiffProcessingWorkV1,n:usize)->Result<(),ValueTreeError>{let n=u64::try_from(n).map_err(|_|limited())?;p.steps_remaining=p.steps_remaining.checked_sub(n.checked_add(1).ok_or_else(limited)?).ok_or_else(limited)?;p.bytes_remaining=p.bytes_remaining.checked_sub(n).ok_or_else(limited)?;Ok(())}
fn value<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(field:DiplomacyFieldV1,path:Path,kind:Kind,ctx:&mut WorldFieldReadContextV1<'_,M,R,E,C>,p:&mut BusinessDiffProcessingWorkV1,max:u64,out:&mut impl Write)->Result<RecordValueV1,ValueTreeError>{pay(p,0)?;let key=path.read(field,ctx)?;let root=ctx.lookup(&key.0)?.ok_or_else(bad)?;closure::primitive(kind,&root,&key,&mut ctx.records(),max,out)}
fn bytes<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(field:DiplomacyFieldV1,path:Path,kind:Kind,ctx:&mut WorldFieldReadContextV1<'_,M,R,E,C>,p:&mut BusinessDiffProcessingWorkV1,max:u64,held:&mut MemoryReservation)->Result<String,ValueTreeError>{let RecordValueV1::Text{utf8_bytes}=value(field,path,kind,ctx,p,max,&mut io::sink())?else{return Err(bad())};let n=usize::try_from(utf8_bytes).map_err(|_|limited())?;pay(p,n.checked_add(size_of::<String>()).ok_or_else(limited)?)?;let mut fee=ctx.values.memory.reserve(n.checked_add(size_of::<String>()).ok_or_else(limited)?,ctx.values.class)?;struct Out{bytes:Vec<u8>,bound:usize}impl Write for Out{fn write(&mut self,b:&[u8])->io::Result<usize>{if self.bytes.len().checked_add(b.len()).filter(|n|*n<=self.bound).is_none(){return Err(io::Error::other("diplomacy projection text bound"))}self.bytes.extend_from_slice(b);Ok(b.len())}fn flush(&mut self)->io::Result<()>{Ok(())}}let mut out=Out{bytes:Vec::with_capacity(n),bound:n};if out.bytes.capacity()!=n{return Err(limited())}if value(field,path,kind,ctx,p,max,&mut out)?!=(RecordValueV1::Text{utf8_bytes})||out.bytes.len()!=n{return Err(bad())}pay(p,n)?;let decoded=String::from_utf8(out.bytes);ctx.check()?;let decoded=decoded.map_err(|_|bad())?;held.merge(&mut fee).map_err(ValueTreeError::Invalid)?;Ok(decoded)}
fn json_value<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(field:DiplomacyFieldV1,path:Path,kind:Kind,ctx:&mut WorldFieldReadContextV1<'_,M,R,E,C>,p:&mut BusinessDiffProcessingWorkV1,max:u64)->Result<ReservedValue<Vec<u8>>,ValueTreeError>{let memory=ctx.values.memory.clone();macro_rules! json{($v:expr)=>{crate::incremental_world_rule_projection_delta::encode_original_projection_json_data_v1(&$v,&memory,p,&mut ctx.cancelled)};}match kind{Kind::Text|Kind::Enum(_)=>{let mut fee=memory.reserve(0,ctx.values.class)?;let text=bytes(field,path,kind,ctx,p,max,&mut fee)?;json!(text)},_=>match value(field,path,kind,ctx,p,max,&mut io::sink())?{RecordValueV1::Unit=>json!(()),RecordValueV1::Unsigned(v)=>json!(v),RecordValueV1::Signed(v)=>json!(v),RecordValueV1::Bool(v)=>json!(v),_=>Err(bad())}}}
pub(super) fn scalar_json<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(field:DiplomacyFieldV1,slot:usize,ctx:&mut WorldFieldReadContextV1<'_,M,R,E,C>,p:&mut BusinessDiffProcessingWorkV1,max:u64)->Result<Option<(&'static str,ReservedValue<Vec<u8>>)>,ValueTreeError>{let specs=profile::specs(field);let spec=specs.get(slot).ok_or_else(bad)?;let name=match spec.path{Path::Field(name)=>return Ok(Some((name,json_value(field,spec.path,spec.kind,ctx,p,max)?))),Path::Flag(name)|Path::Value(name)=>name,_=>return Ok(None)};pay(p,specs.len().checked_mul(64).ok_or_else(limited)?)?;let selected=specs.iter().find(|spec|spec.path==Path::Value(name)).ok_or_else(bad)?;let flag=specs.get(selected.flag.ok_or_else(bad)?).ok_or_else(bad)?;let RecordValueV1::Bool(present)=value(field,flag.path,Kind::Bool,ctx,p,1,&mut io::sink())?else{return Err(bad())};if present{Ok(Some((name,json_value(field,selected.path,selected.kind,ctx,p,max)?)))}else{let memory=ctx.values.memory.clone();Ok(Some((name,crate::incremental_world_rule_projection_delta::encode_original_projection_json_data_v1(&(),&memory,p,&mut ctx.cancelled)?)))}}
pub(super) fn member_json<M:MerkleNodeReader,R:ValueNodeReader,E:FnMut()->Option<ValueTreeError>,C:FnMut()->bool>(field:DiplomacyFieldV1,index:u64,ctx:&mut WorldFieldReadContextV1<'_,M,R,E,C>,p:&mut BusinessDiffProcessingWorkV1,max:u64)->Result<ReservedValue<Vec<u8>>,ValueTreeError>{if field==DiplomacyFieldV1::Alliances{return json_value(field,Path::Ordinal("members",index),Kind::Text,ctx,p,max)}if field!=DiplomacyFieldV1::Wars{return Err(bad())}let memory=ctx.values.memory.clone();pay(p,size_of::<WarParticipantOutcome>())?;let mut held=memory.reserve(size_of::<WarParticipantOutcome>(),ctx.values.class)?;let agent_id=bytes(field,Path::OutcomeField(index,"agent_id"),Kind::Text,ctx,p,max,&mut held)?;macro_rules! signed{($name:literal)=>{match value(field,Path::OutcomeField(index,$name),Kind::I64,ctx,p,8,&mut io::sink())?{RecordValueV1::Signed(v)=>v,_=>return Err(bad())}};}let dto=WarParticipantOutcome{agent_id,electricity_delta:signed!("electricity_delta"),data_delta:signed!("data_delta"),reputation_delta:signed!("reputation_delta")};crate::incremental_world_rule_projection_delta::encode_original_projection_json_data_v1(&dto,&memory,p,&mut ctx.cancelled)}
